java.awt.image.BufferedImage rectImage = new java.awt.image.BufferedImage(200, 100, java.awt.image.BufferedImage.TYPE_INT_ARGB);
net.coobird.thumbnailator.filters.ImageFilter filter = net.coobird.thumbnailator.filters.Rotation.newRotator(90.0);
java.awt.image.BufferedImage rotatedImage = filter.apply(rectImage);

assert rotatedImage.getWidth() == 100 : "Expected width 100, got " + rotatedImage.getWidth();
assert rotatedImage.getHeight() == 200 : "Expected height 200, got " + rotatedImage.getHeight();
assert rotatedImage != rectImage : "Original image should not be mutated in place";

System.out.println("__CHECK__ newRotator " + rotatedImage.getWidth() + "x" + rotatedImage.getHeight());

